import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import PhoneSalesFilterForm from './PhoneSalesFilterForm';
import PhoneSalesInputForm from './PhoneSalesInputForm';
import PhoneSalesResult from './PhoneSalesResult';
import { phonePlans } from '../config/phonePlanConfig';

export default function PhoneSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    devicePrice: 0,
    partialPayment: 0,
    subsidyAmount: 0,
    discountType: '',
    installments: 24,
    pensionApply: '' // 기초연금 수급 여부
  });

  const [results, setResults] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  // 필터 변경 핸들러
  const handleFilterChange = (name, value) => {
    setValues(prev => {
      const next = { ...prev, [name]: value };
      if (name === 'planId') {
        const plan = phonePlans.find(p => p.id === value) || {};
        next.planCost = plan.monthlyFee || 0;
      }
      if (name === 'category') {
        next.planId = '';
        next.planCost = 0;
      }
      if (name === 'dataFilter') {
        next.category = '';
        next.planId = '';
        next.planCost = 0;
      }
      return next;
    });
    setResults(null);
    setRecommendedDiscount('');
  };

  // 폼 입력 변경 핸들러
  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({
      ...prev,
      [name]: ['installments', 'partialPayment', 'subsidyAmount', 'devicePrice'].includes(name)
        ? Number(value)
        : value
    }));
    setResults(null);
    setRecommendedDiscount('');
  };

  const isSenior = values.category === '5G 시니어 (만 65세 이상)';
  const hasPension = values.pensionApply === 'yes';

  // 계산 가능 여부
  const canCalc =
    values.planCost > 0 &&
    values.devicePrice > 0 &&
    values.discountType !== '' &&
    (!isSenior || values.pensionApply !== '');

  // 계산 로직
  const handleCalculate = () => {
    if (!canCalc) return;
    const { planCost, devicePrice, partialPayment, subsidyAmount, discountType, installments } = values;

    // 기본 단말원금
    const basePrincipal = devicePrice - partialPayment;
    const principalSubsidy = basePrincipal - subsidyAmount;

    // 기초연금 할인액
    let appliedPensionDiscount = 0;
    if (isSenior && hasPension) {
      appliedPensionDiscount = Math.min(planCost * 0.5, 12100);
    }

    // 월 요금제 비용 (원가 유지)
    const monthlyPlanCost = planCost;

    // 단말 할부 계산
    const deviceInstallmentContract = installments > 0
      ? Math.ceil((basePrincipal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const deviceInstallmentSubsidy = installments > 0
      ? Math.ceil((principalSubsidy * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;

    // 선택된 할인 유형별 단말 할부
    const deviceInstallment =
      values.discountType === 'subsidy'
        ? deviceInstallmentSubsidy
        : deviceInstallmentContract;

    // 총 납부 기본 합계
    const baseTotal = monthlyPlanCost + deviceInstallment;
    // 기초연금 할인 적용(총납부에서만)
    const totalPayment = isSenior && hasPension
      ? baseTotal - appliedPensionDiscount
      : baseTotal;

    // 절감액(추천 할인) 계산
    const totalSubsidyScenario = planCost + deviceInstallmentSubsidy;
    const totalContractScenario = planCost * 0.75 + deviceInstallmentContract;
    const savings =
      discountType === 'contract'
        ? totalSubsidyScenario - totalContractScenario
        : totalContractScenario - totalSubsidyScenario;
    const recommended =
      totalContractScenario < totalSubsidyScenario
        ? '요금할인'
        : '공시 지원금';

    setResults({ monthlyPlanCost, deviceInstallment, totalPayment, savings, appliedPensionDiscount });
    setRecommendedDiscount(recommended);
  };

  return (
    <div className="flex flex-col items-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-lg bg-white shadow rounded-2xl p-6 mb-4">
        <h2 className="text-2xl font-bold mb-6 text-center">KT 핸드폰 상담 계산기</h2>
        <p className="mt-2 text-base font-bold text-red-500">주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.</p>

        <PhoneSalesFilterForm values={values} onFilterChange={handleFilterChange} />
        <PhoneSalesInputForm
          values={values}
          onChange={handleChange}
          others={phonePlans.find(p => p.id === values.planId)?.others}
          recommendedDiscount={recommendedDiscount}
        />

        <button
          type="button"
          onClick={handleCalculate}
          disabled={!canCalc}
          className={`w-full py-2 rounded-md mb-4 transition ${canCalc
            ? 'bg-blue-500 text-white hover:bg-blue-600'
            : 'bg-gray-300 text-gray-600 cursor-not-allowed'}`}
        >
          계산하기
        </button>

        {results && (
          <PhoneSalesResult
            {...results}
            discountType={values.discountType}
            pensionApply={values.pensionApply}
          />
        )}

        <div className="mt-2 w-full text-center">
          <button
            onClick={() => navigate('/')}
            className="w-full px-4 py-2 bg-gray-200 rounded hover:bg-gray-300"
          >
            메인 메뉴로 돌아가기
          </button>
        </div>
      </div>
    </div>
  );
}
